-- Metro Shoes sample data and report queries. Run after schema.sql.
PRAGMA foreign_keys = ON;
BEGIN;
COMMIT;

-- ===== Report queries (results) =====
-- Q1 sales by day
SELECT * FROM v_sales_by_day ORDER BY day;
-- Q2 best sellers
SELECT * FROM v_best_sellers LIMIT 5;
-- Q3 low stock variants
SELECT * FROM v_low_stock ORDER BY available, name;
-- Q4 orders by stage
SELECT stage, COUNT(*) AS orders FROM orders GROUP BY stage ORDER BY orders DESC;
-- Q5 average hours from placement to confirmation
SELECT ROUND(AVG((c.changed_at - o.placed_at)/3600000.0),2) AS avg_hours FROM orders o JOIN order_status_log c ON c.order_id=o.order_id AND c.stage='Confirmed';
-- Q6 revenue by currency
SELECT currency, COUNT(*) AS orders, ROUND(SUM(total),2) AS total FROM orders WHERE stage NOT IN ('Cancelled','Returned') GROUP BY currency;
-- Q7 stock value on hand (PKR)
SELECT ROUND(SUM(v.on_hand*COALESCE(p.sale_pkr,p.price_pkr)),2) AS stock_value_pkr FROM variants v JOIN products p USING(product_id);
-- Q8 open fire-safety actions
SELECT zone, item, note FROM fire_checks WHERE status='Action';
